$n=0;function check(bool $ok,string $why):void{global $n;if(!$ok)throw new RuntimeException($why);++$n;echo "PASS $why\n";}function denied(callable $fn,string $why):void{try{$fn();}catch(DomainException){check(true,$why);return;}throw new RuntimeException($why);}
$key=static fn()=>bin2hex(random_bytes(16));$service=new InvoiceSupplierContacts($db,'admin');$registry=new Registry($db,'admin');
$company=$service->create(['name'=>'Synthetic Supplier'],$key());$id=$company['id'];$foreign=(new InvoiceSupplierContacts($db,'other'))->create(['name'=>'Other synthetic supplier'],$key());$person=$registry->saveContact(null,0,'person','Synthetic Person','','');
$docs=new Documents($db,'admin');$doc=$docs->upload('synthetic.xml','<Invoice xmlns="urn:synthetic:bank-profile"/>',['title'=>'Original','kind'=>'receipt','scope'=>'finance','links'=>[]],$key());$entry=(new InvoiceInbox($db,'admin'))->create($doc,1,['description'=>'Original expense','amount'=>'119','category'=>'general','document_date'=>'2026-09-08','due_date'=>'2026-09-30','supplier_contact'=>$id,'supplier_version'=>'1'],$key(),'general','SYNTH-1');
