$bank1=['iban'=>'de89 3704 0044 0532 0130 00','bic'=>'cobadeffxxx'];$bank2=['iban'=>'DE12500105170648489890','bic'=>'INGDDEFFXXX'];
check($service->bank($id)===['iban'=>'','bic'=>''],'absent bank details are empty');
foreach(['reader','finance','contacts','member'] as $actor){$limited=new InvoiceSupplierContacts($db,$actor);denied(fn()=>$limited->saveBank($id,1,$bank1),'both write rights required for save: '.$actor);denied(fn()=>$limited->removeBank($id,1),'both write rights required for removal: '.$actor);}
denied(fn()=>$service->saveBank($foreign['id'],1,$bank1),'foreign club supplier blocked');denied(fn()=>$service->saveBank($person,1,$bank1),'person is not a supplier company');
foreach([['iban'=>'','bic'=>'COBADEFFXXX'],['iban'=>'DE89370400440532013001'],['iban'=>[]],['iban'=>$bank1['iban'],'bic'=>'bad-bic']] as $bad)denied(fn()=>$service->saveBank($id,1,$bad),'invalid bank fields do not save');
check($registry->contact($id)['version']===1&&$service->bank($id)['iban']==='','failed writes leave contact version and bank unchanged');
check((new InvoiceSupplierContacts($db,'writer'))->saveBank($id,1,$bank1)===2,'ordinary user with both write rights can save and receives new contact version');check($service->bank($id)===['iban'=>'DE89370400440532013000','bic'=>'COBADEFFXXX'],'bank values normalized');
check((new InvoiceSupplierContacts($db,'reader'))->bank($id)===$service->bank($id),'read-only finance and contact role may read');denied(fn()=>(new InvoiceSupplierContacts($db,'contacts'))->bank($id),'contact permission alone cannot read bank');
denied(fn()=>$service->saveBank($id,1,$bank2),'stale save blocked');denied(fn()=>$service->removeBank($id,1),'stale removal blocked');check($service->bank($id)['iban']==='DE89370400440532013000'&&$registry->contact($id)['version']===2,'stale writes leave current bank unchanged');
check($service->saveBank($id,2,$bank2)===3&&$service->bank($id)===$bank2,'current bank can be changed');
$saved=$service->bank($id);$events=(int)$db->query('SELECT COUNT(*) FROM audit_events')->fetchColumn();$db->exec("CREATE TRIGGER reject_bank_audit BEFORE INSERT ON audit_events FOR EACH ROW BEGIN IF NEW.action IN ('supplier.bank.saved','supplier.bank.removed') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic audit failure'; END IF; END");
foreach([fn()=>$service->saveBank($id,3,$bank1),fn()=>$service->removeBank($id,3)] as $attempt){try{$attempt();throw new RuntimeException('Expected atomic audit failure.');}catch(PDOException){check($service->bank($id)===$saved&&$registry->contact($id)['version']===3&&(int)$db->query('SELECT COUNT(*) FROM audit_events')->fetchColumn()===$events,'audit failure rolls back bank and contact version');}}
$db->exec('DROP TRIGGER reject_bank_audit');
$db->prepare('UPDATE contacts SET archived_at=? WHERE id=?')->execute([gmdate('c'),$id]);denied(fn()=>$service->saveBank($id,3,$bank1),'archived supplier blocked');$db->prepare('UPDATE contacts SET archived_at=NULL WHERE id=?')->execute([$id]);
check($service->removeBank($id,3)===4&&$service->bank($id)===['iban'=>'','bic'=>''],'explicit removal keeps contact and advances its version');denied(fn()=>$service->removeBank($id,4),'missing details are not audited as removed');
check(count($registry->contacts())===$count&&$finance->entry($entry)===$originalEntry&&$service->forEntry($entry)===$snapshot&&$docs->file($doc)===$original,'company count, invoice snapshot and original remain unchanged');
$audit=$db->query("SELECT * FROM audit_events WHERE action LIKE 'supplier.bank.%' ORDER BY sequence")->fetchAll(PDO::FETCH_ASSOC);check(count($audit)===3&&array_column($audit,'object_version')===[2,3,4],'save/change/removal audit records carry correct versions');check(array_column($audit,'actor_id')===['writer','admin','admin']&&!str_contains(json_encode($audit),'DE8937')&&!str_contains(json_encode($audit),'DE1250'),'audit identifies actor without bank numbers');check(\Kulturhus\Verein\Tests\MySqlFixture::integrity($db)==='ok'&&!(\Kulturhus\Verein\Tests\MySqlFixture::foreignKeyErrors($db)[0]??false),'database integrity');echo "$n supplier bank checks passed; isolated memory database, no network or mail\n";
